/** Read-aloud for a sentence, with word-level callbacks for highlighting.
 *
 *  Engines:
 *   - "recorded": audio generated by the pipeline (pipeline/audio.py): a
 *     neural voice reading our phonetic transcription of the Greek in the
 *     reconstructed pronunciation. One MP3 per passage plus an index with
 *     each sentence's offset and estimated word start times. Played with an
 *     <audio> element so the speed control keeps the pitch.
 *   - "system": the browser's own speech synthesis with a Modern Greek voice,
 *     the fallback when no recording exists.
 */

export type EngineName = 'recorded' | 'system';

export interface SpeakRequest {
  textId: string;
  passageId: string;
  sentenceId: string;
  text: string;                 // plain sentence text, for the system voice
  rate: number;                 // 1 = as recorded; 0.6 .. 1.3
  onWord?: (wordIndex: number, charStart: number) => void;  // index among non-punct tokens; char offset for the system voice
  onEnd?: () => void;
  onError?: (message: string) => void;
}

export interface Handle { stop: () => void }

interface Segment { t: number; d: number; w: number[] }
interface PassageAudio { f: string; s: Record<string, Segment> }
type AudioIndex = Record<string, PassageAudio>;

const indexCache = new Map<string, Promise<AudioIndex | null>>();
let player: HTMLAudioElement | null = null;

function assetUrl(file: string): string {
  const base = import.meta.env.BASE_URL.replace(/\/$/, '');
  return new URL(`${base}/${file}`, document.baseURI).href;
}

export function loadAudioIndex(textId: string): Promise<AudioIndex | null> {
  if (!indexCache.has(textId)) {
    indexCache.set(textId, fetch(assetUrl(`audio/${textId}.json`)).then((r) => (r.ok ? r.json() : null)).catch(() => null));
  }
  return indexCache.get(textId)!;
}

export async function hasRecording(textId: string, passageId: string): Promise<boolean> {
  const idx = await loadAudioIndex(textId);
  return !!idx?.[passageId];
}

function getPlayer(): HTMLAudioElement {
  if (!player) {
    player = new Audio();
    player.preload = 'auto';
  }
  return player;
}

async function speakRecorded(req: SpeakRequest): Promise<Handle | null> {
  const idx = await loadAudioIndex(req.textId);
  const entry = idx?.[req.passageId];
  const seg = entry?.s[req.sentenceId];
  if (!entry || !seg) return null;
  const a = getPlayer();
  const src = assetUrl(`audio/${entry.f}`);
  if (a.src !== src) {
    a.src = src;
    a.load();
  }
  if (a.readyState < 1) {
    await new Promise<void>((resolve, reject) => {
      const ok = () => { cleanup(); resolve(); };
      const bad = () => { cleanup(); reject(new Error('audio file could not be loaded')); };
      const cleanup = () => { a.removeEventListener('loadedmetadata', ok); a.removeEventListener('error', bad); };
      a.addEventListener('loadedmetadata', ok);
      a.addEventListener('error', bad);
    });
  }
  const rate = Math.min(1.5, Math.max(0.5, req.rate));
  a.playbackRate = rate;
  // keep the pitch when slowing down (default in current browsers, set explicitly where supported)
  (a as HTMLAudioElement & { preservesPitch?: boolean }).preservesPitch = true;
  a.currentTime = seg.t / 1000;
  const timers: number[] = [];
  let stopped = false;
  const finish = () => {
    if (stopped) return;
    stopped = true;
    timers.forEach(clearTimeout);
    a.removeEventListener('ended', finish);
    a.pause();
    req.onEnd?.();
  };
  a.addEventListener('ended', finish);
  await a.play();
  const t0 = performance.now();
  seg.w.forEach((ms, i) => {
    const delay = Math.max(0, (ms - seg.t) / rate);
    timers.push(window.setTimeout(() => { if (!stopped) req.onWord?.(i, -1); }, delay));
  });
  // stop at the end of the segment, checked against the element's clock to survive buffering
  const endAt = (seg.t + seg.d) / 1000;
  const tick = () => {
    if (stopped) return;
    if (a.currentTime >= endAt - 0.02 || a.paused && performance.now() - t0 > 500 && a.currentTime >= endAt - 0.2) { finish(); return; }
    timers.push(window.setTimeout(tick, 60));
  };
  tick();
  return { stop: finish };
}

/** Play a clip from a recorded file (used by the alphabet page). */
export async function playClip(file: string, t: number, d: number, rate = 1, onEnd?: () => void): Promise<Handle> {
  const a = getPlayer();
  const src = assetUrl(`audio/${file}`);
  if (a.src !== src) { a.src = src; a.load(); }
  if (a.readyState < 1) {
    await new Promise<void>((resolve, reject) => {
      const ok = () => { cleanup(); resolve(); };
      const bad = () => { cleanup(); reject(new Error('audio file could not be loaded')); };
      const cleanup = () => { a.removeEventListener('loadedmetadata', ok); a.removeEventListener('error', bad); };
      a.addEventListener('loadedmetadata', ok);
      a.addEventListener('error', bad);
    });
  }
  a.playbackRate = Math.min(1.5, Math.max(0.5, rate));
  (a as HTMLAudioElement & { preservesPitch?: boolean }).preservesPitch = true;
  a.currentTime = t / 1000;
  let stopped = false;
  let timer = 0;
  const finish = () => { if (stopped) return; stopped = true; clearTimeout(timer); a.pause(); onEnd?.(); };
  await a.play();
  const endAt = (t + d) / 1000;
  const tick = () => { if (stopped) return; if (a.currentTime >= endAt - 0.02 || a.ended) { finish(); return; } timer = window.setTimeout(tick, 50); };
  tick();
  return { stop: finish };
}

const clipIndexCache = new Map<string, Promise<Record<string, { t: number; d: number }> | null>>();
export function loadClipIndex(name: string) {
  if (!clipIndexCache.has(name)) clipIndexCache.set(name, fetch(assetUrl(`audio/${name}.json`)).then((r) => (r.ok ? r.json() : null)).catch(() => null));
  return clipIndexCache.get(name)!;
}

// ---------------------------------------------------------------- system voice

export function systemGreekVoice(): SpeechSynthesisVoice | null {
  if (typeof speechSynthesis === 'undefined') return null;
  return speechSynthesis.getVoices().find((v) => /^el/i.test(v.lang)) ?? null;
}

async function speakSystem(req: SpeakRequest): Promise<Handle> {
  if (typeof speechSynthesis === 'undefined') throw new Error('This browser has no speech synthesis');
  speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(req.text);
  const v = systemGreekVoice();
  if (v) u.voice = v;
  u.lang = v?.lang ?? 'el-GR';
  u.rate = req.rate;
  let done = false;
  u.onboundary = (e) => { if (e.name === 'word' && !done) req.onWord?.(-1, e.charIndex); };
  u.onend = () => { if (!done) { done = true; req.onEnd?.(); } };
  u.onerror = (e) => { if (!done) { done = true; req.onError?.(e.error); req.onEnd?.(); } };
  speechSynthesis.speak(u);
  return { stop: () => { if (!done) { done = true; speechSynthesis.cancel(); req.onEnd?.(); } } };
}

// ---------------------------------------------------------------- entry

/** Speak with the chosen engine; falls back to the system voice when there is
 *  no recording for the sentence. Resolves to the handle and the engine used. */
export async function speak(engine: EngineName, req: SpeakRequest): Promise<{ handle: Handle; engine: EngineName }> {
  if (engine === 'recorded') {
    const h = await speakRecorded(req);
    if (h) return { handle: h, engine: 'recorded' };
  }
  return { handle: await speakSystem(req), engine: 'system' };
}

/** Join tokens into the string to speak; returns the text and each token's
 *  start offset in it (punctuation attached to the previous word). */
export function sentenceText(forms: string[], isPunct: (f: string) => boolean): { text: string; starts: number[] } {
  let text = '';
  const starts: number[] = [];
  forms.forEach((f, i) => {
    if (i > 0 && !isPunct(f)) text += ' ';
    starts.push(text.length);
    text += f;
  });
  return { text, starts };
}

/** Token index for a character offset reported by the system voice. */
export function tokenAtChar(starts: number[], forms: string[], pos: number, isPunct: (f: string) => boolean): number {
  let best = -1;
  for (let i = 0; i < starts.length; i++) {
    if (isPunct(forms[i])) continue;
    if (starts[i] <= pos + 1) best = i; else break;
  }
  return best;
}

/** Token index of the n-th non-punctuation token. */
export function tokenAtWord(forms: string[], n: number, isPunct: (f: string) => boolean): number {
  let k = -1;
  for (let i = 0; i < forms.length; i++) {
    if (isPunct(forms[i])) continue;
    k++;
    if (k === n) return i;
  }
  return -1;
}
